EXPORT RASTERCONTROL() BEGIN
  Base:=3; Bits:=32; Signed:=0;
  RECT_P(0,0,319,239,#FFFFFFh,#FFFFFFh);
  LOCAL x,y,out:={};
  FOR y FROM 0 TO 3 DO
    FOR x FROM 0 TO 4 DO
      PIXON_P(x,y,RGB(10*x+1,20*y+3,31*(x+y)));
    END;
  END;
  BLIT_P(G0,1,1,5,4,G0,0,0,3,3,RGB(11,23,62),160);
  FOR y FROM 0 TO 3 DO
    FOR x FROM 0 TO 4 DO
      out:=CONCAT(out,{B→R(GETPIX_P(G0,x,y))});
    END;
  END;
  RETURN out;
END;

EXPORT ZZT_EMPTY() BEGIN LOCAL r,out:={};
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,2,1,2,3,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,1,2,3,2,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,3,3,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,2,1,1,3,G2); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,0,0,0,2,G1); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G1),GROBH_P(G1)}});
DIMGROB_P(G1,3,3,#FF0000h);DIMGROB_P(G2,5,2,#C00000h);
r:=1; IFERR SUBGROB_P(G1,3,3,G2);DIMGROB_P(G2,1,1,#A00000h); THEN r:=0; END;
out:=CONCAT(out,{{r,GROBW_P(G2),GROBH_P(G2)}});
RETURN out; END;

EXPORT ZZT_MESHPT() BEGIN
RECT_P(#020406h);
LOCAL ok,typ,r,x,y,out,zz;
ok:=1; typ:=-1; out:={};
zz:=TRIANGLE_P();
IFERR
r:=LINE_P([[(0,4),(20,8935920)],[(7,4),(20,8935920)]],{{1,2}},{-1},zz);
typ:=TYPE(r);
THEN ok:=0; END;
FOR y FROM 0 TO 6 DO FOR x FROM 0 TO 8 DO
 out:=CONCAT(out,{B→R(GETPIX_P(x,y))});
END; END;
RETURN {ok,typ,out,ASC(MID(zz,641,5))};
END;

EXPORT ZZT_DEPTHSCREEN() BEGIN
RECT_P(#020406h);
LOCAL zz,tmp,x,y,out,accepted,old;
zz:=TRIANGLE_P(); old:=zz;
accepted:=1; out:={};
IFERR
tmp:=LINE_P({{0,2,32},{7,2,32}},{{1,2,#3355EEh}},{-1},zz);
tmp:=LINE_P({{0,2,0},{7,2,80}},{{1,2,#FE7420h}},{-1},zz);
THEN accepted:=0; END;
FOR y FROM 0 TO 6 DO FOR x FROM 0 TO 8 DO
 out:=CONCAT(out,{B→R(GETPIX_P(x,y))});
END; END;
RETURN {accepted,TYPE(tmp),out,ASC(MID(zz,321,5)),ASC(LEFT(old,1))};
END;

EXPORT ZZT_NDEPTHSCREEN() BEGIN
RECT_P(#020406h);
LOCAL zz,r,accepted,x,y,pixels,kind;
zz:=TRIANGLE_P(); accepted:=1; kind:=-1; pixels:={};
IFERR
 r:=LINE_P({{0,2,70},{7,2,70}},{{1,2,#3355EEh}},{-1},zz);
r:=LINE_P({{0,2,-3},{7,2,37}},{{1,2,#FE7420h}},{-1,"N"},zz);
 kind:=TYPE(r);
THEN accepted:=0; END;
FOR y FROM 0 TO 6 DO FOR x FROM 0 TO 8 DO
 pixels:=CONCAT(pixels,{B→R(GETPIX_P(x,y))});
END; END;
RETURN {accepted,kind,pixels,ASC(MID(zz,321,9))}; END;
